import React, { useContext, useEffect } from "react";
import { GoogleLogin } from "@react-oauth/google";
import { useNavigate } from "react-router-dom";
import { jwtDecode } from "jwt-decode"; 
import { UserContext } from "./UserContext";  // Import User Context
import "./LoginPage.css";
import "./base.css"

const LoginPage = () => {
  const navigate = useNavigate();
  const { user, login, logout } = useContext(UserContext);  // Access global user state

  // Check if user is already logged in & navigate to home
  useEffect(() => {
    if (user) {
      navigate("/home");
    }
  }, [user, navigate]);  // Runs only when user changes

  // Handle Google Login Success
  const handleGoogleLoginSuccess = (response) => {
    try {
      const decodedUser = jwtDecode(response.credential); // Decode the token
      console.log("Google Login Success:", decodedUser);

      login(decodedUser);  // Save user in context & localStorage
      navigate("/home");   // Redirect to Home Page
    } catch (error) {
      console.error("Error decoding Google token:", error);
    }
  };

  // Handle Google Login Failure
  const handleGoogleLoginFailure = () => {
    console.log("Google Login Failed");
  };

  return (
    <div className="login-page">
      <header className="header">
        <h1 className="logo">
          <span className="bold">Channel-</span>
          <span className="highlight">IQ</span>
        </h1>
        <nav className="nav">
          {user && ( // Show logout only if user is logged in
            <button className="sign-out" onClick={logout}>
              Logout
            </button>
          )}
        </nav>
      </header>

      <div className="login-container">
        <div className="left-panel">
          <h1>
            Channel-<span className="highlight">IQ</span>
          </h1>
          <p>
            Turn your long videos into <span className="highlight">VIRAL</span> short clips.
          </p>
          <ul>
            <li>✔ AI SEO</li>
            <li>✔ Auto Caption</li>
            <li>✔ Auto Clipping</li>
            <li>✔ Quality Enhancer</li>
            <li>✔ Sound Improvement</li>
          </ul>
        </div>

        <div className="right-panel">
          <h2>{user ? `Welcome, ${user.name}` : "Login to your account"}</h2>

          {user ? (
            <button className="logout-btn" onClick={logout}>
              Logout
            </button>
          ) : (
            <GoogleLogin
              onSuccess={handleGoogleLoginSuccess}
              onError={handleGoogleLoginFailure}
            />
          )}
        </div>
      </div>
    </div>
  );
};

export default LoginPage;
